/* @lc app=leetcode id=3720 lang=kotlin */ class Solution { fun lexGreaterPermutation(s: String, target: String): String = IntArray(26).also { cs -> s.forEach { cs[it - 'a']++ } }.let { cs -> (target.length - 1 downTo 0).firstNotNullOfOrNull { p -> IntArray(26) { a -> cs[a] - target.take(p).count { c -> c - 'a' == a } }.let { rem -> if (rem.any { it < 0 }) null else ((target[p] - 'a' + 1)..25).firstOrNull { rem[it] > 0 }?.let { c -> rem.copyOf().also { it[c]-- }.let { r2 -> target.take(p) + ('a' + c) + (0..25).joinToString("") { a -> ('a' + a).toString().repeat(r2[a]) } } } } } ?: "" } }